-- Learning content authoring draft; root promotes/applies after review.
begin;
alter table app.units add column content_preparation boolean not null default false;alter table app.lessons add column content_preparation boolean not null default false;alter table app.activities add column content_preparation boolean not null default false;
create table app.learning_content_revisions(school_id uuid not null,id uuid not null default gen_random_uuid(),resource text not null check(resource in('course','unit','lesson','activity')),source_id uuid not null,course_id uuid not null,revision integer not null check(revision>0),title text not null check(length(btrim(title))between 1 and 200),content text not null check(length(content)<=50000),kind text,assessment_id uuid,state text not null check(state in('DRAFT','PUBLISHED','RETIRED')),reason text not null check(length(btrim(reason))between 1 and 1000),created_by uuid not null,created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),unique(school_id,resource,source_id,revision),unique(school_id,id,resource,source_id),foreign key(school_id,course_id)references app.courses(school_id,id),foreign key(school_id,assessment_id)references app.assessments(school_id,id),foreign key(school_id,created_by)references app.memberships(school_id,actor_id),check((resource='course'and length(content)<=4000 and kind is null and assessment_id is null)or(resource='unit'and content=''and kind is null and assessment_id is null)or(resource='lesson'and length(btrim(content))>0 and kind is null and assessment_id is null)or(resource='activity'and length(btrim(content))between 1 and 10000 and kind in('reading','practice','assignment','quiz','reflection'))));
create table app.learning_content_current(school_id uuid not null,resource text not null,source_id uuid not null,draft_revision_id uuid not null,published_revision_id uuid,primary key(school_id,resource,source_id),foreign key(school_id,draft_revision_id,resource,source_id)references app.learning_content_revisions(school_id,id,resource,source_id),foreign key(school_id,published_revision_id,resource,source_id)references app.learning_content_revisions(school_id,id,resource,source_id));
create table app.learning_completion_context(school_id uuid not null,completion_id uuid not null,course_revision_id uuid not null,unit_revision_id uuid not null,lesson_revision_id uuid not null,activity_revision_id uuid not null,primary key(school_id,completion_id),foreign key(school_id,completion_id)references app.activity_completions(school_id,id),foreign key(school_id,course_revision_id)references app.learning_content_revisions(school_id,id),foreign key(school_id,unit_revision_id)references app.learning_content_revisions(school_id,id),foreign key(school_id,lesson_revision_id)references app.learning_content_revisions(school_id,id),foreign key(school_id,activity_revision_id)references app.learning_content_revisions(school_id,id));
create table app.learning_submission_context(school_id uuid not null,submission_id uuid not null,course_revision_id uuid not null,assessment_title text not null,assessment_instructions text not null,preparation_version integer not null,policy_version integer not null,primary key(school_id,submission_id),foreign key(school_id,submission_id)references app.submissions(school_id,id),foreign key(school_id,course_revision_id)references app.learning_content_revisions(school_id,id));
create table app.learning_submission_activity_context(school_id uuid not null,submission_id uuid not null,activity_revision_id uuid not null,primary key(school_id,submission_id,activity_revision_id),foreign key(school_id,submission_id)references app.submissions(school_id,id),foreign key(school_id,activity_revision_id)references app.learning_content_revisions(school_id,id));
create function internal.learning_content_course(target_resource text,target_source uuid)returns uuid language sql stable security definer set search_path=''as $$select case target_resource when'course'then(select id from app.courses where school_id="authorization".school_id()and id=target_source)when'unit'then"authorization".unit_course("authorization".school_id(),target_source)when'lesson'then"authorization".lesson_course("authorization".school_id(),target_source)when'activity'then"authorization".activity_course("authorization".school_id(),target_source)end$$;
create function internal.learning_content_initial()returns trigger language plpgsql security definer set search_path=''as $$declare resource text;course uuid;title text;content text;kind text;state text;rid uuid;actor uuid;begin
 resource:=case tg_table_name when'courses'then'course'when'units'then'unit'when'lessons'then'lesson'else'activity'end;title:=new.title;kind:=case when resource='activity'then to_jsonb(new)->>'kind'else null end;content:=case resource when'course'then to_jsonb(new)->>'description'when'unit'then''when'lesson'then to_jsonb(new)->>'body'else to_jsonb(new)->>'instructions'end;
 course:=case resource when'course'then new.id when'unit'then(to_jsonb(new)->>'course_id')::uuid when'lesson'then"authorization".unit_course(new.school_id,(to_jsonb(new)->>'unit_id')::uuid)else"authorization".lesson_course(new.school_id,(to_jsonb(new)->>'lesson_id')::uuid)end;
 actor:=case when resource='course'then(to_jsonb(new)->>'created_by')::uuid else(select created_by from app.courses where school_id=new.school_id and id=course)end;
 state:=case when resource='course'and to_jsonb(new)->>'status'='DRAFT'or coalesce((to_jsonb(new)->>'content_preparation')::boolean,false)or(resource='activity'and kind in('assignment','quiz'))then'DRAFT'else'PUBLISHED'end;
 insert into app.learning_content_revisions(school_id,resource,source_id,course_id,revision,title,content,kind,state,reason,created_by)values(new.school_id,resource,new.id,course,1,title,content,kind,state,'Original school-authored source registered.',actor)returning id into rid;insert into app.learning_content_current(school_id,resource,source_id,draft_revision_id,published_revision_id)values(new.school_id,resource,new.id,rid,case when state='PUBLISHED'then rid else null end);return new;
end$$;
-- Existing source identity remains; snapshots are explicit current original contexts only.
insert into app.learning_content_revisions(school_id,resource,source_id,course_id,revision,title,content,kind,state,reason,created_by)
select school_id,'course',id,id,1,title,description,null,case when status='DRAFT'then'DRAFT'else'PUBLISHED'end,'Existing current school source registered; older learner context remains unknown.',created_by from app.courses
union all select u.school_id,'unit',u.id,u.course_id,1,u.title,'',null,'PUBLISHED','Existing current school source registered; older learner context remains unknown.',c.created_by from app.units u join app.courses c on c.school_id=u.school_id and c.id=u.course_id
union all select l.school_id,'lesson',l.id,u.course_id,1,l.title,l.body,null,'PUBLISHED','Existing current school source registered; older learner context remains unknown.',c.created_by from app.lessons l join app.units u on u.school_id=l.school_id and u.id=l.unit_id join app.courses c on c.school_id=u.school_id and c.id=u.course_id
union all select a.school_id,'activity',a.id,u.course_id,1,a.title,a.instructions,a.kind,'PUBLISHED','Existing current school source registered; older learner context remains unknown.',c.created_by from app.activities a join app.lessons l on l.school_id=a.school_id and l.id=a.lesson_id join app.units u on u.school_id=l.school_id and u.id=l.unit_id join app.courses c on c.school_id=u.school_id and c.id=u.course_id;
insert into app.learning_content_current(school_id,resource,source_id,draft_revision_id,published_revision_id)select school_id,resource,source_id,id,case when state='PUBLISHED'then id else null end from app.learning_content_revisions;
create trigger content_initial after insert on app.courses for each row execute function internal.learning_content_initial();create trigger content_initial after insert on app.units for each row execute function internal.learning_content_initial();create trigger content_initial after insert on app.lessons for each row execute function internal.learning_content_initial();create trigger content_initial after insert on app.activities for each row execute function internal.learning_content_initial();
create function internal.learning_content_projection(target_revision uuid)returns jsonb language sql stable security definer set search_path=''as $$select jsonb_build_object('id',r.id,'courseId',r.course_id,'resource',r.resource,'sourceId',r.source_id,'revision',r.revision,'title',r.title,'content',r.content,'kind',r.kind,'assessmentId',r.assessment_id,'state',r.state,'createdAt',r.created_at,'publishedRevision',p.revision,'draftRevision',d.revision)from app.learning_content_revisions r join app.learning_content_current pointer on pointer.school_id=r.school_id and pointer.resource=r.resource and pointer.source_id=r.source_id join app.learning_content_revisions d on d.school_id=pointer.school_id and d.id=pointer.draft_revision_id left join app.learning_content_revisions p on p.school_id=pointer.school_id and p.id=pointer.published_revision_id where r.school_id="authorization".school_id()and r.id=target_revision$$;
create function internal.learning_content_ancestors_visible(target_resource text,target_source uuid)returns boolean language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();course uuid;unit uuid;lesson uuid;begin
 course:=internal.learning_content_course(target_resource,target_source);if target_resource='course'then return true;end if;
 if target_resource='unit'then unit:=target_source;elsif target_resource='lesson'then lesson:=target_source;select l.unit_id into unit from app.lessons l where l.school_id=school and l.id=lesson;else select a.lesson_id into lesson from app.activities a where a.school_id=school and a.id=target_source;select l.unit_id into unit from app.lessons l where l.school_id=school and l.id=lesson;end if;
 return exists(select 1 from app.learning_content_current p join app.learning_content_revisions r on r.school_id=p.school_id and r.id=p.published_revision_id where p.school_id=school and p.resource='course'and p.source_id=course and r.state='PUBLISHED') and(target_resource='unit'or exists(select 1 from app.learning_content_current p join app.learning_content_revisions r on r.school_id=p.school_id and r.id=p.published_revision_id where p.school_id=school and p.resource='unit'and p.source_id=unit and r.state='PUBLISHED'))and(target_resource in('unit','lesson')or exists(select 1 from app.learning_content_current p join app.learning_content_revisions r on r.school_id=p.school_id and r.id=p.published_revision_id where p.school_id=school and p.resource='lesson'and p.source_id=lesson and r.state='PUBLISHED'));
end$$;
create function internal.learning_published_content(target_school uuid,target_resource text,target_source uuid)returns jsonb language sql stable security definer set search_path=''as $$select jsonb_build_object('revisionId',r.id,'revision',r.revision,'title',r.title,'content',r.content,'kind',r.kind,'assessmentId',r.assessment_id)from app.learning_content_current p join app.learning_content_revisions r on r.school_id=p.school_id and r.id=p.published_revision_id where p.school_id=target_school and p.resource=target_resource and p.source_id=target_source and r.state='PUBLISHED'and internal.learning_content_ancestors_visible(target_resource,target_source)$$;
create function internal.learning_content_visible(target_resource text,target_source uuid)returns boolean language sql stable security definer set search_path=''as $$select coalesce(exists(select 1 from app.learning_content_current p join app.learning_content_revisions selected on selected.school_id=p.school_id and selected.id=case when"authorization".can_manage_course(p.school_id,(select r.course_id from app.learning_content_revisions r where r.school_id=p.school_id and r.id=p.draft_revision_id))then p.draft_revision_id else p.published_revision_id end where p.school_id="authorization".school_id()and p.resource=target_resource and p.source_id=target_source and"authorization".can_read_course(p.school_id,selected.course_id)and("authorization".can_manage_course(p.school_id,selected.course_id)or(selected.state<>'RETIRED'and internal.learning_content_ancestors_visible(target_resource,target_source)))),false)$$;
create function internal.read_learning_content_set(targets jsonb)returns jsonb language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();course uuid;items jsonb;begin
 if targets is null or jsonb_typeof(targets)<>'array'or jsonb_array_length(targets)>1201 or jsonb_array_length(targets)<>(select count(distinct (entry->>'resource')||':'||(entry->>'id'))from jsonb_array_elements(targets)entry) or exists(select 1 from jsonb_array_elements(targets)t where jsonb_typeof(t)<>'object'or t-array['resource','id']<>'{}'::jsonb or t->>'resource'is null or t->>'resource'not in('course','unit','lesson','activity')or jsonb_typeof(t->'id')is distinct from'string')then raise exception 'Bounded source content set required'using errcode='22023';end if;
 if exists(select 1 from jsonb_array_elements(targets)t where not internal.learning_content_visible(t->>'resource',(t->>'id')::uuid))then raise exception 'Current visible source set denied'using errcode='42501';end if;
 select coalesce(jsonb_agg(internal.learning_content_projection(selected.id)),'[]'::jsonb)into items from jsonb_array_elements(targets)t join app.learning_content_current p on p.school_id=school and p.resource=t->>'resource'and p.source_id=(t->>'id')::uuid join app.learning_content_revisions selected on selected.school_id=p.school_id and selected.id=case when"authorization".can_manage_course(school,(select r.course_id from app.learning_content_revisions r where r.school_id=p.school_id and r.id=p.draft_revision_id))then p.draft_revision_id else p.published_revision_id end;
 if octet_length(items::text)>500000 then raise exception 'Current content page exceeds read bound'using errcode='22023';end if;return items;
end$$;
create function internal.read_learning_content(target_resource text,target_source uuid,history boolean,filters jsonb)returns jsonb language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();course uuid;pointer app.learning_content_current;items jsonb;lim integer;cursor_id uuid;staff boolean;begin
 course:=internal.learning_content_course(target_resource,target_source);if course is null or not"authorization".can_read_course(school,course)then raise exception 'Current content source denied'using errcode='42501';end if;staff:="authorization".can_manage_course(school,course);
 select c.*into pointer from app.learning_content_current c where c.school_id=school and c.resource=target_resource and c.source_id=target_source;if not found then raise exception 'Content source unavailable'using errcode='42501';end if;
 if not history then if not staff and(not internal.learning_content_ancestors_visible(target_resource,target_source)or pointer.published_revision_id is null or exists(select 1 from app.learning_content_revisions r where r.school_id=school and r.id=pointer.published_revision_id and r.state='RETIRED')) then raise exception 'Published content source unavailable'using errcode='42501';end if;return internal.learning_content_projection(case when staff then pointer.draft_revision_id else pointer.published_revision_id end);end if;
 if not staff then raise exception 'Content author history required'using errcode='42501';end if;lim:=(filters->>'limit')::integer;cursor_id:=(filters->>'cursor')::uuid;if lim is null or lim not between 1 and 25 then raise exception 'Bounded source history required'using errcode='22023';end if;
 select coalesce(jsonb_agg(internal.learning_content_projection(r.id)order by r.id),'[]'::jsonb)into items from(select r.id from app.learning_content_revisions r where r.school_id=school and r.resource=target_resource and r.source_id=target_source and(cursor_id is null or r.id>cursor_id)order by r.id limit lim+1)r;if octet_length(items::text)>500000 then raise exception 'Content history requires a smaller review page'using errcode='22023';end if;return jsonb_build_object('items',case when jsonb_array_length(items)>lim then items-lim else items end,'nextCursor',case when jsonb_array_length(items)>lim then items->(lim-1)->>'id'else null end);
end$$;
create function internal.learning_content_source_guard()returns trigger language plpgsql security definer set search_path=''as $$declare source_course uuid;begin
 source_course:=case new.resource when'course'then(select id from app.courses where school_id=new.school_id and id=new.source_id)when'unit'then"authorization".unit_course(new.school_id,new.source_id)when'lesson'then"authorization".lesson_course(new.school_id,new.source_id)else"authorization".activity_course(new.school_id,new.source_id)end;if source_course is null or source_course is distinct from new.course_id then raise exception 'Exact content source course required'using errcode='42501';end if;return new;
end$$;
create trigger content_source_guard before insert on app.learning_content_revisions for each row execute function internal.learning_content_source_guard();
create function internal.learning_content_command(command_name text,target_resource text,target_source uuid,payload jsonb,command_key text,fingerprint text,request_id text)returns jsonb language plpgsql security definer set search_path=''as $$declare school uuid:="authorization".school_id();course uuid;pointer app.learning_content_current;current app.learning_content_revisions;assessment app.assessments;reservation jsonb;rid uuid;next_revision integer;receipt jsonb;begin
 course:=internal.learning_content_course(target_resource,target_source);if course is null or not"authorization".can_manage_course(school,course)or not"authorization".has_entitlement(school,'learning')then raise exception 'Content author course denied'using errcode='42501';end if;
 if command_name='retire'then perform 1 from app.courses c where c.school_id=school and c.id=course for update;else perform internal.require_curriculum_academic_write(course);end if;
 select p.*into pointer from app.learning_content_current p where p.school_id=school and p.resource=target_resource and p.source_id=target_source for update;if not found then raise exception 'Exact content source unavailable'using errcode='42501';end if;select r.*into current from app.learning_content_revisions r where r.school_id=school and r.id=pointer.draft_revision_id;
 if command_name is null or command_name not in('draft','publish','retire')or payload is null or jsonb_typeof(payload)<>'object'or jsonb_typeof(payload->'expectedRevision')is distinct from'number'or(payload->>'expectedRevision')!~'^[1-9][0-9]*$'then raise exception 'Expected current content revision required'using errcode='22023';end if;
 reservation:=internal.begin_command(command_key,'learning.content.'||command_name,fingerprint);if reservation->>'state'='COMPLETED'then return internal.learning_content_projection((reservation->'response'->>'id')::uuid);elsif reservation->>'state'<>'NEW'then raise exception 'Content command pending'using errcode='22023';end if;
 if current.revision is distinct from(payload->>'expectedRevision')::integer or current.state='RETIRED'then raise exception 'Content revision changed or retired'using errcode='22023';end if;
 next_revision:=current.revision+1;
 if command_name='draft'then
  if payload-array['resource','expectedRevision','title','content','kind','assessmentId','reason']<>'{}'::jsonb or payload->>'resource'is distinct from target_resource or jsonb_typeof(payload->'title')is distinct from'string'or length(btrim(payload->>'title'))not between 1 and 200 or jsonb_typeof(payload->'content')is distinct from'string'or length(payload->>'content')>50000 or jsonb_typeof(payload->'reason')is distinct from'string'or length(btrim(payload->>'reason'))not between 1 and 1000 then raise exception 'Content draft fields invalid'using errcode='22023';end if;
  if target_resource='activity'then
   if payload->>'kind'is distinct from current.kind then raise exception 'Activity kind is immutable; create a new activity'using errcode='22023';end if;
   if payload->>'kind'is null or payload->>'kind'not in('reading','practice','assignment','quiz','reflection')or length(btrim(payload->>'content'))not between 1 and 10000 or((payload->>'kind'in('assignment','quiz'))is distinct from(payload->>'assessmentId'is not null))then raise exception 'Exact activity task source required'using errcode='22023';end if;
   if payload->>'assessmentId'is not null then select a.*into assessment from app.assessments a where a.school_id=school and a.id=(payload->>'assessmentId')::uuid and a.course_id=course for share;if not found or(payload->>'kind'='quiz'and coalesce(assessment.intended_submission_kind,assessment.submission_kind)<>'QUIZ')or(payload->>'kind'='assignment'and coalesce(assessment.intended_submission_kind,assessment.submission_kind)<>'TEXT')then raise exception 'Same-course matching assessment required'using errcode='42501';end if;end if;
  elsif payload->>'kind'is not null or payload->>'assessmentId'is not null or(target_resource='unit'and payload->>'content'<>'')or(target_resource='course'and length(payload->>'content')>4000)or(target_resource='lesson'and length(btrim(payload->>'content'))=0)then raise exception 'Content shape differs from owner'using errcode='22023';end if;
  insert into app.learning_content_revisions(school_id,resource,source_id,course_id,revision,title,content,kind,assessment_id,state,reason,created_by)values(school,target_resource,target_source,course,next_revision,payload->>'title',payload->>'content',payload->>'kind',(payload->>'assessmentId')::uuid,'DRAFT',payload->>'reason',"authorization".actor_id())returning id into rid;
  update app.learning_content_current p set draft_revision_id=rid where p.school_id=school and p.resource=target_resource and p.source_id=target_source;
 elsif command_name='publish'then
  if payload-array['expectedRevision','confirmPublication']<>'{}'::jsonb or payload->'confirmPublication'is distinct from'true'::jsonb or current.state<>'DRAFT'then raise exception 'Explicit draft publication required'using errcode='22023';end if;
  if current.resource='activity'and current.kind in('assignment','quiz')then select a.*into assessment from app.assessments a where a.school_id=school and a.id=current.assessment_id and a.course_id=course for share;if not found or assessment.status<>'PUBLISHED'or(current.kind='quiz'and assessment.submission_kind<>'QUIZ')or(current.kind='assignment'and assessment.submission_kind<>'TEXT')then raise exception 'Published exact assessment required'using errcode='22023';end if;end if;
  insert into app.learning_content_revisions(school_id,resource,source_id,course_id,revision,title,content,kind,assessment_id,state,reason,created_by)values(school,target_resource,target_source,course,next_revision,current.title,current.content,current.kind,current.assessment_id,'PUBLISHED','Teacher explicitly published the reviewed content.',"authorization".actor_id())returning id into rid;
  update app.learning_content_current p set draft_revision_id=rid,published_revision_id=rid where p.school_id=school and p.resource=target_resource and p.source_id=target_source;
  if target_resource='course'then perform internal.publish_learning_course_children(target_source);update app.courses c set status='PUBLISHED'where c.school_id=school and c.id=target_source;end if;
 else
  if payload-array['expectedRevision','reason','confirmRetirement']<>'{}'::jsonb or payload->'confirmRetirement'is distinct from'true'::jsonb or jsonb_typeof(payload->'reason')is distinct from'string'or length(btrim(payload->>'reason'))not between 1 and 1000 then raise exception 'Explicit content retirement required'using errcode='22023';end if;
  if target_resource='course'and exists(select 1 from app.assessments a where a.school_id=school and a.course_id=course and(a.assignment_state='OPEN'or exists(select 1 from app.current_submissions c where c.school_id=a.school_id and c.assessment_id=a.id and c.state<>'CLOSED')))then raise exception 'Resolve open course work before retiring content'using errcode='22023';end if;
  insert into app.learning_content_revisions(school_id,resource,source_id,course_id,revision,title,content,kind,assessment_id,state,reason,created_by)values(school,target_resource,target_source,course,next_revision,current.title,current.content,current.kind,current.assessment_id,'RETIRED',payload->>'reason',"authorization".actor_id())returning id into rid;update app.learning_content_current p set draft_revision_id=rid,published_revision_id=rid where p.school_id=school and p.resource=target_resource and p.source_id=target_source;
 end if;
 receipt:=internal.learning_content_projection(rid);perform internal.append_audit('learning.content.'||command_name,'learning_content',rid,request_id,'succeeded',jsonb_build_object('resource',target_resource,'sourceId',target_source,'revision',next_revision));perform internal.enqueue_event('learning.content.changed','learning_content',rid,next_revision,'{}','learning-content:'||rid::text);perform internal.finish_command(command_key,'learning.content.'||command_name,fingerprint,jsonb_build_object('id',rid));return receipt;
end$$;
-- Legacy publish surfaces publish the same current source and never restore retired content.
create function internal.read_activity_task_choices(target_activity uuid,page_limit integer,page_cursor uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();course uuid;activity app.activities;items jsonb;begin
 course:="authorization".activity_course(school,target_activity);if not"authorization".has_entitlement(school,'assessment')or course is null or not"authorization".can_manage_course(school,course)or page_limit is null or page_limit not between 1 and 100 then raise exception 'Current activity author task choices denied'using errcode='42501';end if;
 select a.*into activity from app.activities a where a.school_id=school and a.id=target_activity;
 select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'title',a.title,'courseId',a.course_id,'submissionKind',a.submission_kind,'intendedSubmissionKind',a.intended_submission_kind,'status',a.status)order by a.id),'[]'::jsonb)into items from(select a.*from app.assessments a where a.school_id=school and a.course_id=course and(page_cursor is null or a.id>page_cursor)and(case when activity.kind='quiz'then coalesce(a.intended_submission_kind,a.submission_kind)='QUIZ'when activity.kind='assignment'then coalesce(a.intended_submission_kind,a.submission_kind)='TEXT'else false end)order by a.id limit page_limit+1)a;
 return jsonb_build_object('items',case when jsonb_array_length(items)>page_limit then items-page_limit else items end,'nextCursor',case when jsonb_array_length(items)>page_limit then items->(page_limit-1)->>'id'else null end);
end$$;
create function internal.publish_learning_course_children(target_course uuid)returns void language plpgsql security definer set search_path=''as $$declare school uuid:="authorization".school_id();child app.learning_content_revisions;assessment app.assessments;rid uuid;begin
 if not"authorization".can_manage_course(school,target_course)then raise exception 'Course content publication author required'using errcode='42501';end if;
 for child in select r.*from app.learning_content_current p join app.learning_content_revisions r on r.school_id=p.school_id and r.id=p.draft_revision_id where p.school_id=school and r.course_id=target_course and p.resource<>'course'and r.state='DRAFT'order by case r.resource when'unit'then 1 when'lesson'then 2 else 3 end,p.source_id for update of p loop
  if child.resource='activity'and child.kind in('assignment','quiz')then select a.*into assessment from app.assessments a where a.school_id=school and a.id=child.assessment_id and a.course_id=target_course;if not found or assessment.status<>'PUBLISHED'or(child.kind='quiz'and assessment.submission_kind<>'QUIZ')or(child.kind='assignment'and assessment.submission_kind<>'TEXT')then raise exception 'Connect and publish exact course tasks before publication'using errcode='22023';end if;end if;
  insert into app.learning_content_revisions(school_id,resource,source_id,course_id,revision,title,content,kind,assessment_id,state,reason,created_by)values(school,child.resource,child.source_id,target_course,child.revision+1,child.title,child.content,child.kind,child.assessment_id,'PUBLISHED','Teacher reviewed and published the course content.',"authorization".actor_id())returning id into rid;
  update app.learning_content_current p set draft_revision_id=rid,published_revision_id=rid where p.school_id=school and p.resource=child.resource and p.source_id=child.source_id;
 end loop;
end$$;
create function internal.learning_content_course_published()returns trigger language plpgsql security definer set search_path=''as $$declare pointer app.learning_content_current;draft app.learning_content_revisions;rid uuid;begin
 if new.status='PUBLISHED'and old.status is distinct from new.status then perform internal.publish_learning_course_children(new.id); select p.*into pointer from app.learning_content_current p where p.school_id=new.school_id and p.resource='course'and p.source_id=new.id for update;select r.*into draft from app.learning_content_revisions r where r.school_id=new.school_id and r.id=pointer.draft_revision_id;if draft.state='RETIRED'then raise exception 'Retired course content cannot publish'using errcode='22023';end if;if draft.state='DRAFT'then insert into app.learning_content_revisions(school_id,resource,source_id,course_id,revision,title,content,state,reason,created_by)values(new.school_id,'course',new.id,new.id,draft.revision+1,draft.title,draft.content,'PUBLISHED','Course explicitly published.',"authorization".actor_id())returning id into rid;update app.learning_content_current p set draft_revision_id=rid,published_revision_id=rid where p.school_id=new.school_id and p.resource='course'and p.source_id=new.id;end if;end if;return new;
end$$;
create trigger current_course_publish after update on app.courses for each row execute function internal.learning_content_course_published();

create function internal.learning_content_view(target_resource text,target_source uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();course uuid;pointer app.learning_content_current;selected app.learning_content_revisions;staff boolean;begin
 course:=internal.learning_content_course(target_resource,target_source);if course is null or not"authorization".can_read_course(school,course)then raise exception 'Current learning content denied'using errcode='42501';end if;staff:="authorization".can_manage_course(school,course);select p.*into pointer from app.learning_content_current p where p.school_id=school and p.resource=target_resource and p.source_id=target_source;if not found then raise exception 'Source revision context unavailable'using errcode='42501';end if;
 select r.*into selected from app.learning_content_revisions r where r.school_id=school and r.id=case when staff then pointer.draft_revision_id else pointer.published_revision_id end;if not found or(not staff and(selected.state='RETIRED'or not internal.learning_content_ancestors_visible(target_resource,target_source)))then return null;end if;return internal.learning_content_projection(selected.id);
end$$;
create function internal.learning_content_completion_snapshot()returns trigger language plpgsql security definer set search_path=''as $$declare course uuid;unit uuid;lesson uuid;course_revision uuid;unit_revision uuid;lesson_revision uuid;activity_revision uuid;activity app.learning_content_revisions;begin
 select l.id,u.id,u.course_id into lesson,unit,course from app.activities a join app.lessons l on l.school_id=a.school_id and l.id=a.lesson_id join app.units u on u.school_id=l.school_id and u.id=l.unit_id where a.school_id=new.school_id and a.id=new.activity_id;
 select p.published_revision_id into course_revision from app.learning_content_current p where p.school_id=new.school_id and p.resource='course'and p.source_id=course;select p.published_revision_id into unit_revision from app.learning_content_current p where p.school_id=new.school_id and p.resource='unit'and p.source_id=unit;select p.published_revision_id into lesson_revision from app.learning_content_current p where p.school_id=new.school_id and p.resource='lesson'and p.source_id=lesson;select r.*into activity from app.learning_content_current p join app.learning_content_revisions r on r.school_id=p.school_id and r.id=p.published_revision_id where p.school_id=new.school_id and p.resource='activity'and p.source_id=new.activity_id;
 if course_revision is null or unit_revision is null or lesson_revision is null or activity.id is null or activity.state='RETIRED'or exists(select 1 from app.learning_content_revisions r where r.school_id=new.school_id and r.id in(course_revision,unit_revision,lesson_revision)and r.state='RETIRED')then raise exception 'Current published learning context required'using errcode='22023';end if;
 if activity.kind in('assignment','quiz')and activity.assessment_id is not null then raise exception 'Open the linked assessment; activity completion is not submission'using errcode='22023';end if;
 insert into app.learning_completion_context(school_id,completion_id,course_revision_id,unit_revision_id,lesson_revision_id,activity_revision_id)values(new.school_id,new.id,course_revision,unit_revision,lesson_revision,activity.id);return new;
end$$;
create trigger content_completion_snapshot after insert on app.activity_completions for each row execute function internal.learning_content_completion_snapshot();
create function internal.learning_content_submission_snapshot()returns trigger language plpgsql security definer set search_path=''as $$declare assessment app.assessments;course_revision uuid;begin
 select a.*into assessment from app.assessments a where a.school_id=new.school_id and a.id=new.assessment_id;select p.published_revision_id into course_revision from app.learning_content_current p where p.school_id=new.school_id and p.resource='course'and p.source_id=assessment.course_id;
 if course_revision is null or exists(select 1 from app.learning_content_revisions r where r.school_id=new.school_id and r.id=course_revision and r.state='RETIRED')then raise exception 'Current published course context required'using errcode='22023';end if;
 insert into app.learning_submission_context(school_id,submission_id,course_revision_id,assessment_title,assessment_instructions,preparation_version,policy_version)values(new.school_id,new.id,course_revision,assessment.title,assessment.instructions,assessment.preparation_version,assessment.policy_version);
 insert into app.learning_submission_activity_context(school_id,submission_id,activity_revision_id)select new.school_id,new.id,r.id from app.learning_content_current p join app.learning_content_revisions r on r.school_id=p.school_id and r.id=p.published_revision_id where p.school_id=new.school_id and p.resource='activity'and r.course_id=assessment.course_id and r.assessment_id=assessment.id and r.state='PUBLISHED'and internal.learning_content_ancestors_visible('activity',p.source_id);return new;
end$$;
create trigger content_submission_snapshot after insert on app.submissions for each row execute function internal.learning_content_submission_snapshot();
create function internal.read_activity_assessment(target_activity uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();content jsonb;assessment app.assessments;result jsonb;begin
 if not "authorization".can_read_course(school,"authorization".activity_course(school,target_activity))then raise exception 'Current task course denied'using errcode='42501';end if;content:=internal.learning_published_content(school,'activity',target_activity)||jsonb_build_object('courseId',"authorization".activity_course(school,target_activity),'state','PUBLISHED');if content is null or content->>'state'<>'PUBLISHED'or content->>'kind'not in('assignment','quiz')or content->>'assessmentId'is null then raise exception 'Published linked task required'using errcode='42501';end if;
 select a.*into assessment from app.assessments a where a.school_id=school and a.id=(content->>'assessmentId')::uuid and a.course_id=(content->>'courseId')::uuid;if not found or assessment.status<>'PUBLISHED'or(content->>'kind'='quiz'and assessment.submission_kind<>'QUIZ')or(content->>'kind'='assignment'and assessment.submission_kind<>'TEXT')then raise exception 'Exact same-course task unavailable'using errcode='42501';end if;
 result:=jsonb_build_object('id',assessment.id,'courseId',assessment.course_id,'title',assessment.title,'instructions',assessment.instructions,'model',assessment.model,'rubricId',internal.read_assessment_rubric_identity(school,assessment.id),'status',assessment.status,'dueAt',assessment.due_at,'policyVersion',assessment.policy_version,'availableFrom',assessment.available_from,'availableUntil',assessment.available_until,'allowLate',assessment.allow_late,'assignmentState',assessment.assignment_state,'availabilityVersion',assessment.availability_version,'submissionKind',assessment.submission_kind,'preparationVersion',assessment.preparation_version,'intendedSubmissionKind',assessment.intended_submission_kind,'intendedModel',assessment.intended_model,'referenceId',assessment.academic_reference_id);
 if assessment.model='numeric'then result:=result||jsonb_build_object('maxScore',assessment.max_score);end if;if"authorization".current_role(school)='student'then result:=result||jsonb_build_object('currentSubmission',(select item from jsonb_array_elements(internal.read_own_assessment_submissions(array[assessment.id]))item limit 1));end if;return result;
end$$;
create function internal.read_learning_source_context(target_type text,target_source uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();course uuid;completion app.activity_completions;submission app.submissions;context_course app.learning_content_revisions;context_lesson app.learning_content_revisions;context_activity app.learning_content_revisions;submission_context app.learning_submission_context;begin
 if target_type='submission'then
  if not internal.submitted_work_allowed(target_source)then raise exception 'Submitted source context denied'using errcode='42501';end if;select s.*into submission from app.submissions s where s.school_id=school and s.id=target_source;select c.*into submission_context from app.learning_submission_context c where c.school_id=school and c.submission_id=submission.id;select r.*into context_course from app.learning_content_revisions r where r.school_id=school and r.id=submission_context.course_revision_id;
 elsif target_type='completion'then
  select c.*into completion from app.activity_completions c where c.school_id=school and c.id=target_source;course:="authorization".activity_course(school,completion.activity_id);if completion.id is null or not"authorization".can_read_course(school,course)or not"authorization".current_learner_course(school,course,completion.learner_id)or not(completion.learner_id="authorization".actor_id()or("authorization".can_manage_course(school,course)and"authorization".can_view_person(school,completion.learner_id)))then raise exception 'Learning completion source context denied'using errcode='42501';end if;
  select r.*into context_course from app.learning_completion_context c join app.learning_content_revisions r on r.school_id=c.school_id and r.id=c.course_revision_id where c.school_id=school and c.completion_id=completion.id;select r.*into context_lesson from app.learning_completion_context c join app.learning_content_revisions r on r.school_id=c.school_id and r.id=c.lesson_revision_id where c.school_id=school and c.completion_id=completion.id;select r.*into context_activity from app.learning_completion_context c join app.learning_content_revisions r on r.school_id=c.school_id and r.id=c.activity_revision_id where c.school_id=school and c.completion_id=completion.id;
 else raise exception 'Exact source context type required'using errcode='22023';end if;
 return jsonb_build_object('sourceId',target_source,'contextStatus',case when context_course.id is null then'UNKNOWN'else'AVAILABLE'end,'course',case when context_course.id is null then null else jsonb_build_object('revisionId',context_course.id,'revision',context_course.revision,'title',context_course.title,'content',context_course.content)end,'lesson',case when context_lesson.id is null then null else jsonb_build_object('revisionId',context_lesson.id,'revision',context_lesson.revision,'title',context_lesson.title,'content',context_lesson.content)end,'activity',case when context_activity.id is null then null else jsonb_build_object('revisionId',context_activity.id,'revision',context_activity.revision,'title',context_activity.title,'content',context_activity.content,'kind',context_activity.kind)end,'assessment',case when submission_context.submission_id is null then null else jsonb_build_object('title',submission_context.assessment_title,'instructions',submission_context.assessment_instructions,'preparationVersion',submission_context.preparation_version,'policyVersion',submission_context.policy_version)end);
end$$;
do $$declare definition text;anchor text;begin
 definition:=pg_get_functiondef('internal.require_curriculum_academic_write(uuid)'::regprocedure);anchor:=' perform internal.lock_academic_course';if position(anchor in definition)=0 then raise exception 'Content academic write entry changed'using errcode='22023';end if;
 execute replace(definition,anchor,' if exists(select 1 from app.learning_content_current p join app.learning_content_revisions r on r.school_id=p.school_id and r.id=p.published_revision_id where p.school_id=school and p.resource=''course''and p.source_id=target_course and r.state=''RETIRED'')then raise exception ''Retired course content is read only''using errcode=''22023'';end if;'||anchor);
 definition:=pg_get_functiondef('internal.resource_target_allowed(uuid,text,uuid,boolean)'::regprocedure);anchor:=' return("authorization".current_role';if position(anchor in definition)=0 then raise exception 'Resource current target gate changed'using errcode='22023';end if;
 execute replace(definition,anchor,' if "authorization".current_role(school)=''student''and(case when target_kind=''assessment''then internal.learning_published_content(school,''course'',course)is null else internal.learning_published_content(school,target_kind,target_id)is null end)then return false;end if;'||anchor);
end$$;
-- Stable original content identities cannot be edited around the revision command surface.
create function internal.learning_content_identity_guard()returns trigger language plpgsql set search_path=''as $$begin
 if tg_op='DELETE'then raise exception 'Learning source identity cannot be deleted'using errcode='55000';end if;
 if to_jsonb(new)-'status'is distinct from to_jsonb(old)-'status'then raise exception 'Learning content changes require a reviewed revision'using errcode='55000';end if;return new;
end$$;
create trigger content_identity_immutable before update or delete on app.courses for each row execute function internal.learning_content_identity_guard();create trigger content_identity_immutable before update or delete on app.units for each row execute function internal.learning_content_identity_guard();create trigger content_identity_immutable before update or delete on app.lessons for each row execute function internal.learning_content_identity_guard();create trigger content_identity_immutable before update or delete on app.activities for each row execute function internal.learning_content_identity_guard();
do $$declare tab text;begin foreach tab in array array['learning_content_revisions','learning_content_current','learning_completion_context','learning_submission_context','learning_submission_activity_context']loop execute format('alter table app.%I enable row level security',tab);execute format('alter table app.%I force row level security',tab);execute format('revoke all on app.%I from public,anon,authenticated,service_role,cuevo_api,cuevo_worker',tab);end loop;foreach tab in array array['learning_content_revisions','learning_completion_context','learning_submission_context','learning_submission_activity_context']loop execute format('create trigger immutable_history before update or delete on app.%I for each row execute function internal.academic_history_immutable()',tab);execute format('create trigger immutable_truncate before truncate on app.%I for each statement execute function internal.academic_history_immutable()',tab);end loop;end$$;
revoke execute on function internal.learning_content_course(text,uuid),internal.learning_content_initial(),internal.learning_content_projection(uuid),internal.read_learning_content(text,uuid,boolean,jsonb),internal.learning_content_command(text,text,uuid,jsonb,text,text,text),internal.publish_learning_course_children(uuid),internal.learning_content_course_published(),internal.learning_content_view(text,uuid),internal.learning_content_completion_snapshot(),internal.learning_content_submission_snapshot(),internal.read_activity_assessment(uuid),internal.learning_content_identity_guard(),internal.learning_content_source_guard(),internal.learning_published_content(uuid,text,uuid),internal.learning_content_ancestors_visible(text,uuid),internal.learning_content_visible(text,uuid),internal.read_learning_content_set(jsonb),internal.read_learning_source_context(text,uuid),internal.read_activity_task_choices(uuid,integer,uuid)from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
grant execute on function internal.read_learning_content(text,uuid,boolean,jsonb),internal.learning_content_command(text,text,uuid,jsonb,text,text,text),internal.learning_content_view(text,uuid),internal.read_activity_assessment(uuid),internal.learning_content_visible(text,uuid),internal.read_learning_content_set(jsonb),internal.read_learning_source_context(text,uuid),internal.read_activity_task_choices(uuid,integer,uuid)to cuevo_api;
do $$declare definition text;anchor text;begin definition:=pg_get_functiondef('internal.process_learner_event(uuid,uuid)'::regprocedure);anchor:='begin'||chr(10);if position(anchor in definition)=0 then raise exception 'Content dispatcher shape changed'using errcode='22023';end if;definition:=replace(definition,anchor,'begin'||chr(10)||' if exists(select 1 from internal.outbox_events event where event.id=target_event and event.type=''learning.content.changed'')then select*into e from internal.outbox_events where id=target_event for update;if e.state<>''PROCESSING''or e.lease_token is distinct from current_lease or e.lease_until<=clock_timestamp()or e.entity_type<>''learning_content''or not exists(select 1 from app.learning_content_revisions r where r.school_id=e.school_id and r.id=e.entity_id and r.revision=e.version and r.created_by=e.actor_id)then raise exception ''Learning content event source invalid''using errcode=''22023'';end if;insert into internal.processed_events(event_id,school_id)values(e.id,e.school_id)on conflict(event_id)do nothing;if internal.complete_outbox(e.id,current_lease)is distinct from true then raise exception ''Learning content acknowledgement lease changed''using errcode=''22023'';end if;return jsonb_build_object(''status'',''ACKNOWLEDGED'');end if;'||chr(10));execute definition;end$$;
